+            return;
+        }
+
+        int nextSpace = space + PRINT_INDENT;
+        appendTree(node.right, nextSpace, builder);
+        builder.append('\n');
+        for (int i = PRINT_INDENT; i < nextSpace; i++) {
+            builder.append(' ');
+        }
+        builder.append(node.data).append('\n');
+        appendTree(node.left, nextSpace, builder);
+    }
